insert into public.lm_sources(id,title,url,document_name,locator,limitations,checked_at) values('plan','웹 서비스 제작 구상도',null,'웹_서비스_제작_구상도.pdf','3쪽','수축률 차이 3%포인트·견뢰도 3등급은 팀 기획의 초안 규칙. 검증된 품질 표준 아님.','2026-10-27') on conflict(id) do nothing;
insert into public.lm_sources(id,title,url,document_name,locator,limitations,checked_at) values('denim-profile','데님 원단 조사 프로필','https://www.kci.go.kr/kciportal/landing/article.kci?arti_id=ART001092857','데님원단 조사_.pdf','1-2쪽','프로필의 개별 수치와 원문 시료 연결은 추가 확인 필요. 다른 연구와 합치지 않음.','2026-10-27') on conflict(id) do nothing;
insert into public.lm_sources(id,title,url,document_name,locator,limitations,checked_at) values('denim-wash','세탁방법에 따른 데님직물의 변색과 변형','https://www.kci.go.kr/kciportal/landing/article.kci?arti_id=ART001421538','데님원단 조사_.pdf','2-7쪽; 원문 115-120쪽','제공된 조사 문서를 통해 확인. 원문·재배포 조건 별도 검토 필요. 면100% 특정 연구 시료에 한정.','2026-10-27') on conflict(id) do nothing;
insert into public.lm_sources(id,title,url,document_name,locator,limitations,checked_at) values('blend-profile','면65/폴리35 원단 조사 프로필','https://object-tex.com/shop/fabric/product/12','cotton-폴리에스터 blend_.pdf','1쪽','8-10% 수축과 수축이 적다는 서술이 병존. 시료·측정 조건 미확인으로 수치 분석 제외.','2026-10-27') on conflict(id) do nothing;
insert into public.lm_sources(id,title,url,document_name,locator,limitations,checked_at) values('blend-shirt','반복세탁 및 건조방법이 드레스셔츠의 물성에 미치는 영향(I)','https://koreascience.kr/article/JAKO199923659442800.pdf','cotton-폴리에스터 blend_.pdf','2쪽; 원문 182-183,186-187쪽','면80/폴리20 완제품 셔츠. 면65/폴리35 원단의 값으로 전용 불가.','2026-10-27') on conflict(id) do nothing;
insert into public.lm_sources(id,title,url,document_name,locator,limitations,checked_at) values('blend-thickness','드레스셔츠 소재의 반복세탁과 다림질에 의한 물성변화에 관한 연구','https://repository.sungshin.ac.kr/handle/2025.oak/3061','cotton-폴리에스터 blend_.pdf','3쪽; 원문 10-12,17-18쪽','폴리60/면40. 세탁·건조·다림질의 복합 효과. 면65/폴리35에 일반화 불가.','2026-10-27') on conflict(id) do nothing;
insert into public.lm_sources(id,title,url,document_name,locator,limitations,checked_at) values('blend-dye','이반응형 브릿지 화합물을 이용한 폴리에스테르/면 복합소재의 단일분산염료 일욕염색(II)','https://journal.kci.go.kr/ksdf/archive/articlePdf?artiId=ART001055047','cotton-폴리에스터 blend_.pdf','4-5쪽; 원문 2-4쪽','DBDCBS 특수 처리 폴리65/면35 교직물. 변퇴색과 첨부포 오염 등급을 구분. 세탁 온도·시간 미기재.','2026-10-27') on conflict(id) do nothing;
insert into public.lm_fabrics(id,name,category,composition,structure,stretch,summary,source_ids,data_gaps) values('denim-cotton100','면100% 비신축 데님','denim','{"cotton": 100}'::jsonb,'능직','non_stretch','특정 면100% 비신축 데님 조사. 실제 소유 원단의 물성과 동일하다는 의미가 아닙니다.',array['denim-profile','denim-wash']::text[],array['실제 원단 수축률','실제 원단 견뢰도','가공 이력','관리 라벨']::text[]) on conflict(id) do nothing;
